mapper.select:
SELECT  FROM sys_slow_request
WHERE alerted = '0' AND create_time >= #{since}
ORDER BY create_time ASC, id ASC

SELECT  FROM sys_slow_request

    AND reason = #{reason}
    AND request_uri LIKE CONCAT('%', #{requestUri}, '%')
    AND create_time >= #{beginTime}
    AND create_time <= #{endTime}

ORDER BY id DESC
